set +e; CLEAR='\''0'\''; PREFER='\''frontend'\''; LU='\''f.bahadorifar'\''; PORT='\''21006'\''; MODE='\''off'\''; AM=""; if [ "$CLEAR" = "1" ]; then AM=""; elif [ -n "$PREFER" ]; then AM="$PREFER"; else AM=$(grep -E "^ACTIVE_MOUNT=" "$HOME/.claude-connect.conf" 2>/dev/null | tail -1 | cut -d= -f2-); fi; printf "LAPTOP_USER=%s\nTUNNEL_PORT=%s\nGIT_MODE=%s\nLAPTOP_OS=windows\nACTIVE_MOUNT=%s\n" "$LU" "$PORT" "$MODE" "$AM" > "$HOME/.claude-connect.conf"
